 "content": "def transform(grid):
    h = len(grid)
    seen = set()
    components = []
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = set()
            while stack:
                x, y = stack.pop()
                cells.add((x, y))
                for dx in (-1, 0, 1):
                    for dy in (-1, 0, 1):
                        nx, ny = x + dx, y + dy
                        if (0 <= nx < h and 0 <= ny < len(grid[nx])
                                and grid[nx][ny] != 0 and (nx, ny) not in seen):
                            seen.add((nx, ny))
                            stack.append((nx, ny))
            components.append(cells)

    def bounds(obj):
        return (min(r for r, _ in obj), max(r for r, _ in obj),
                min(c for _, c in obj), max(c for _, c in obj))

    def asymmetry(obj):
        r0, r1, c0, c1 = bounds(obj)
        hh, ww = r1 - r0 + 1, c1 - c0 + 1
        mask = {(r - r0, c - c0) for r, c in obj}
        # Count mismatches under horizontal and vertical reflection.
        vertical = sum(((r, c) in mask) != ((r, ww - 1 - c) in mask)
                       for r in range(hh) for c in range(ww))
        horizontal = sum(((r, c) in mask) != ((hh - 1 - r, c) in mask)
                         for r in range(hh) for c in range(ww))
        return vertical + horizontal

    target = max(components, key=asymmetry)
    r0, r1, c0, c1 = bounds(target)
    return [[grid[r][c] if (r, c) in target else 0
             for c in range(c0, c1 + 1)] for r in range(r0, r1 + 1)]
